  "summary": "The code suffers from critical performance issues due to blocking I/O in an async context and lacks robust error handling or caching for external dependencies. Overall code health is poor, requiring a transition to asynchronous HTTP clients and defensive programming practices.",
  "fixed_code": "import httpx\nfrom fastapi import FastAPI, HTTPException\nfrom functools import lru_cache\nimport time\n\napp = FastAPI()\nRATES_URL = \"https://api.rates.example.com/v1/latest\"\n\n@lru_cache(maxsize=1)\ndef get_cached_rates(ttl: int = 3600):\n    # Simple cache helper; in production use redis/aiocache\n    return None\n\n@app.get(\"/convert\")\nasync def convert(amount: float, currency: str):\n    \"\"\"Converts a given amount from USD to the target currency using an external API.\"\"\"\n    async with httpx.AsyncClient() as client:\n        try:\n            response = await client.get(RATES_URL, params={\"base\": \"USD\"}, timeout=5.0)\n            response.raise_for_status()\n            data = response.json()\n        except (httpx.RequestError, httpx.HTTPStatusError) as e:\n            raise HTTPException(status_code=502, detail=\"External API error\")\n\n    rates = data.get(\"rates\", {})\n    if currency not in rates:\n        raise HTTPException(status_code=400, detail=\"Invalid currency\")\n\n    return {\"amount\": amount * rates[currency], \"currency\": currency}"
}
